void main() {
  // Test the sorting logic: dates as strings (ISO format: YYYY-MM-DD)
  final dates = ['2026-09-15', '2026-09-01', '2026-09-10', '', '2026-08-20'];

  dates.sort((a, b) {
    final x = a, y = b;
    if (x.isEmpty != y.isEmpty) return x.isEmpty ? 1 : -1;
    final nx = num.tryParse(x), ny = num.tryParse(y);
    final c = (nx != null && ny != null) ? nx.compareTo(ny) : x.compareTo(y);
    if (c != 0) return c;
    return 0;
  });

  print('Sorted dates: $dates');
  // Expected: 2026-08-20, 2026-09-01, 2026-09-10, 2026-09-15, (empty)
}
